begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.cid(text) returns uuid language sql immutable as $$select md5('trial-credit-test-'||$1)::uuid$$;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select pg_temp.cid(u),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',u||'@credits.example.test','','{}','{}',now(),now() from unnest(array['owner','viewer','outsider','manager'])u;
insert into organizations(id,name,slug,industry) values(pg_temp.cid('org'),'Credits','trial-credits','salon'),(pg_temp.cid('other'),'Other','trial-credits-other','salon');
insert into organization_memberships(id,organization_id,user_id,role) values
(pg_temp.cid('owner-member'),pg_temp.cid('org'),pg_temp.cid('owner'),'owner'),(pg_temp.cid('viewer-member'),pg_temp.cid('org'),pg_temp.cid('viewer'),'viewer'),(pg_temp.cid('manager-member'),pg_temp.cid('org'),pg_temp.cid('manager'),'manager'),(pg_temp.cid('other-member'),pg_temp.cid('other'),pg_temp.cid('outsider'),'owner');
insert into branches(id,organization_id,name,is_primary) values(pg_temp.cid('main'),pg_temp.cid('org'),'Main',true),(pg_temp.cid('branch2'),pg_temp.cid('org'),'Second',false),(pg_temp.cid('other-branch'),pg_temp.cid('other'),'Other',true);
insert into membership_branch_assignments(organization_id,membership_id,branch_id) values(pg_temp.cid('org'),pg_temp.cid('viewer-member'),pg_temp.cid('main'));
insert into customers(id,organization_id,full_name) select pg_temp.cid('customer-'||n),pg_temp.cid('org'),'Client '||lpad(n::text,3,'0') from generate_series(1,51)n;
insert into appointments(id,organization_id,branch_id,customer_id,starts_at,expected_duration_minutes,status) select pg_temp.cid('visit-'||n),pg_temp.cid('org'),pg_temp.cid('main'),pg_temp.cid('customer-'||n),now(),30,'completed' from generate_series(1,51)n;
create function pg_temp.payload(kind text default 'clients',action text default 'advanced_report',branch uuid default null) returns jsonb language sql as $$select jsonb_build_object('kind',kind,'action',action,'start',current_date-2,'end',current_date+1,'branch',branch)$$;

-- Reports have an explicit metered Free path; other entitlements remain plan-only.
create function pg_temp.balance() returns integer language sql as $$select (public.get_credit_usage(pg_temp.cid('org'))->>'remaining')::integer$$;
insert into trial_credit_accounts(organization_id,remaining) values(pg_temp.cid('org'),73);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select is(pg_temp.balance(),73,'existing one-time balance preserved exactly');
select is(pg_temp.balance(),73,'opening migration is idempotent');
select ok(not public.get_org_entitlements(pg_temp.cid('org')) ? 'trialCredits','entitlements do not expose billing balances');
select is(public.get_credit_usage(pg_temp.cid('org'))->>'nextRefresh',null,'unconfigured plan has no refresh date');
select is((public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('locked'),pg_temp.payload())->>'cost')::integer,1,'Free report consumes one approved credit');
select is(public.prepare_credit_image(pg_temp.cid('org'),pg_temp.cid('locked-image'),repeat('a',64),'png')->>'code','FEATURE_NOT_ENTITLED','credits cannot unlock uploads');
select is(public.can_upload_business_image(pg_temp.cid('org')||'/photo.png','{}'),false,'Free storage writes rejected');
select throws_ok($$select public.get_client_purchase_report(pg_temp.cid('org'),current_date-2,current_date+1)$$,'42501',null,'direct premium RPC denied');
select throws_ok($$select public.ensure_credit_period(pg_temp.cid('org'))$$,'42501',null,'user cannot self grant');
select throws_ok($$update public.trial_credit_accounts set remaining=100$$,'42501',null,'legacy account cannot be refilled');
select throws_ok($$insert into public.trial_report_context values(pg_temp.cid('org'),txid_current())$$,'42501',null,'cannot enable legacy temporary entitlement');
select throws_ok($$select public.get_credit_usage(pg_temp.cid('other'))$$,'42501',null,'cross-tenant balance denied');
select throws_ok($$select public.platform_credit_usage(pg_temp.cid('org'))$$,'42501',null,'platform reader denied to owner');
select lives_ok($$select public.get_appointment_report(pg_temp.cid('org'),current_date-6,current_date,pg_temp.cid('main'))$$,'Free recent basic report stays usable');
select throws_ok($$select public.get_appointment_report(pg_temp.cid('org'),current_date-90,current_date,pg_temp.cid('main'))$$,'42501',null,'Free historical filter blocked at database');
reset role;
insert into organization_subscriptions(organization_id,plan_id,provider,status,current_period_end) values(pg_temp.cid('org'),'starter','manual','active',now()+interval '1 month') on conflict(organization_id) do update set plan_id='starter',provider='manual',status='active',current_period_end=excluded.current_period_end;
set local role authenticated;
select lives_ok($$select public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'),pg_temp.payload())$$,'paid snapshot generated');
select is(jsonb_array_length(public.read_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'))->'report'->'rows'),51,'saved report contains all matching clients');
select is((public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'),pg_temp.payload())->>'cost')::integer,0,'paid report and retry have no configured cost');
select throws_ok($$select public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'),pg_temp.payload('overview'))$$,'22023',null,'snapshot retry payload bound');
select throws_ok($$select public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('cross'),pg_temp.payload('clients','advanced_report',pg_temp.cid('other-branch')))$$,'42501',null,'paid report cannot cross tenant');
select is((public.prepare_credit_image(pg_temp.cid('org'),pg_temp.cid('image1'),repeat('a',64),'png')->>'completed')::boolean,false,'paid upload prepared');
select throws_ok($$select public.prepare_credit_image(pg_temp.cid('org'),pg_temp.cid('image1'),repeat('b',64),'png')$$,'22023',null,'upload retry payload bound');
reset role;
insert into storage.objects(bucket_id,name,metadata) values('business-images',pg_temp.cid('org')||'/'||pg_temp.cid('image1')||'.png','{"size":100}');
set local role authenticated;
select is((public.prepare_credit_image(pg_temp.cid('org'),pg_temp.cid('image1'),repeat('a',64),'png')->>'completed')::boolean,true,'committed upload safely replayed');
select is(pg_temp.balance(),72,'paid reports and images do not add credit charges');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('manager'),'role','authenticated')::text,true);
select throws_ok($$select public.get_credit_usage(pg_temp.cid('org'))$$,'42501',null,'manager cannot read owner billing usage');
select throws_ok($$select public.get_credit_notices(pg_temp.cid('org'))$$,'42501',null,'manager not billing notification recipient');
select throws_ok($$select public.read_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'))$$,'42501',null,'snapshot actor isolation retained');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('viewer'),'role','authenticated')::text,true);
select throws_ok($$select public.get_command_center_shared_metrics(pg_temp.cid('org'),array[pg_temp.cid('main')])$$,'42501',null,'staff financial dashboard payload denied');
select throws_ok($$select public.get_command_center_activity(pg_temp.cid('org'),array[pg_temp.cid('main')])$$,'42501',null,'staff cannot use owner operational aggregate');
select throws_ok($$select public.generate_credit_report(pg_temp.cid('org'),pg_temp.cid('bad-branch'),pg_temp.payload('clients','advanced_report',pg_temp.cid('branch2')))$$,'42501',null,'paid reports preserve branch assignments');
reset role;
update organization_subscriptions set plan_id='free',status='free' where organization_id=pg_temp.cid('org');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.read_credit_report(pg_temp.cid('org'),pg_temp.cid('report1'))$$,'downgrade preserves existing snapshot data');
select is(public.can_upload_business_image(pg_temp.cid('org')||'/new.png','{}'),false,'downgrade prevents new uploads');
reset role;
select is((select count(*) from storage.objects where name=pg_temp.cid('org')||'/'||pg_temp.cid('image1')||'.png'),1::bigint,'downgrade preserves existing image');
select is((select count(*) from organization_credit_grants where organization_id=pg_temp.cid('org') and credit_class='plan'),0::bigint,'no recurring credits granted by unconfigured plans');
select * from finish();
rollback;
